<script setup lang="ts">
import { onMounted, ref } from 'vue'
type Patient={id:number;full_name:string}
type Cadre={id:number;full_name:string;nik:string;phone:string;rt?:string;rw?:string;birth_place?:string;birth_date?:string;gender?:string;full_address?:string;photo_path?:string|null;patients?:Patient[];is_active:boolean}
const base=import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1',headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'}
const items=ref<Cadre[]>([]),error=ref(''),loading=ref(true),selected=ref<Cadre|null>(null),editing=ref(false),saving=ref(false),deleting=ref(false)
const patientsOf=(cadre:Cadre)=>cadre.patients??[]
const photo=(cadre:Cadre)=>cadre.photo_path?`/media/profile/${cadre.photo_path}`:'/icons/icon-512.png'
const whatsapp=(phone:string)=>`https://wa.me/${phone.replace(/\D/g,'')}`
const formatDate=(value?:string)=>{if(!value)return '';const [year,month,day]=value.slice(0,10).split('-');return year&&month&&day?`${day}/${month}/${year}`:value}
const displayDate=(value?:string)=>formatDate(value)||'Belum tersedia'
async function load(){loading.value=true;error.value='';try{const r=await fetch(`${base}/cadres?per_page=100`,{headers}),p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal memuat kader.');items.value=p.data}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat kader.'}finally{loading.value=false}}
function detail(item:Cadre){selected.value={...item,birth_date:formatDate(item.birth_date),patients:[...patientsOf(item)]};editing.value=false}
function cancelEdit(){if(!selected.value)return;const original=items.value.find(item=>item.id===selected.value?.id);if(original)detail(original);else editing.value=false}
async function save(){if(!selected.value)return;saving.value=true;error.value='';try{const body={full_name:selected.value.full_name,nik:selected.value.nik,birth_place:selected.value.birth_place,birth_date:selected.value.birth_date,gender:selected.value.gender,phone:selected.value.phone,rt:selected.value.rt,rw:selected.value.rw,full_address:selected.value.full_address,is_active:selected.value.is_active};const r=await fetch(`${base}/cadres/${selected.value.id}`,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(body)}),p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal memperbarui kader.');await load();const updated=items.value.find(item=>item.id===selected.value?.id);if(updated)detail(updated)}catch(e){error.value=e instanceof Error?e.message:'Gagal memperbarui kader.'}finally{saving.value=false}}
async function remove(){if(!selected.value)return;const names=patientsOf(selected.value).map(p=>p.full_name).join(', ')||'belum menangani pasien';if(!confirm(`Yakin menghapus ${selected.value.full_name}?\n\nPasien binaan: ${names}\n\nData kader akan dihapus.`))return;deleting.value=true;try{const r=await fetch(`${base}/cadres/${selected.value.id}`,{method:'DELETE',headers}),p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal menghapus kader.');selected.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menghapus kader.'}finally{deleting.value=false}}
onMounted(load)
</script>

<template><main class="admin-page"><section class="admin-content"><header><div><p>Manajemen data</p><h1>Data Kader</h1><p class="page-subtitle">Kelola pendamping pasien dan wilayah tugasnya.</p></div><a class="add-button" href="/admin/cadres/create">+ Tambah Kader</a></header><section class="panel cadre-table-panel"><p v-if="loading">Memuat data kader…</p><p v-else-if="error" class="login-error">{{error}}</p><div v-else class="table-scroll"><table><thead><tr><th>Nama</th><th>NIK</th><th>No. HP</th><th>RT</th><th>RW</th><th>Pasien Binaan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-if="!items.length"><td colspan="8" class="empty">Belum ada kader.</td></tr><tr v-for="item in items" :key="item.id"><td><b>{{item.full_name}}</b><small>{{patientsOf(item).length}} pasien binaan</small></td><td>{{item.nik}}</td><td>{{item.phone}}</td><td>{{item.rt??'—'}}</td><td>{{item.rw??'—'}}</td><td><span v-if="!patientsOf(item).length">Belum ada pasien</span><ol v-else class="patient-list"><li v-for="patient in patientsOf(item)" :key="patient.id">{{patient.full_name}}</li></ol></td><td><span class="status" :class="item.is_active?'active':'inactive'">{{item.is_active?'Aktif':'Nonaktif'}}</span></td><td><button type="button" class="detail-button" @click="detail(item)">Detail</button></td></tr></tbody></table></div></section></section><div v-if="selected" class="cadre-modal" @click.self="selected=null"><section class="cadre-detail-card" role="dialog" aria-modal="true" aria-labelledby="cadre-detail-title"><button class="modal-close" type="button" aria-label="Tutup detail" @click="selected=null">×</button><div class="detail-hero"><img :src="photo(selected)" alt="Foto kader"><div><small>{{editing?'Edit profil kader':'Profil Kader PMO'}}</small><h2 id="cadre-detail-title">{{selected.full_name}}</h2><span class="status" :class="selected.is_active?'active':'inactive'">{{selected.is_active?'Kader aktif':'Kader nonaktif'}}</span></div><a v-if="!editing" class="wa-hero" :href="whatsapp(selected.phone)" target="_blank" rel="noopener">WhatsApp</a></div><form v-if="editing" class="edit-form" @submit.prevent="save"><h3>Edit data kader</h3><p>Perbarui informasi kader, lalu simpan perubahan.</p><div class="form-grid"><label>Nama lengkap<input v-model="selected.full_name" required></label><label>NIK<input v-model="selected.nik" inputmode="numeric" maxlength="16" required></label><label>Tempat lahir<input v-model="selected.birth_place" required></label><label>Tanggal lahir<input v-model="selected.birth_date" inputmode="numeric" placeholder="DD/MM/YYYY" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" required><small>Format: DD/MM/YYYY</small></label><label>Jenis kelamin<select v-model="selected.gender" required><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label>Nomor HP<input v-model="selected.phone" type="tel" required><small>Awalan nomor gunakan 62.</small></label><label>RT<input v-model="selected.rt" maxlength="3" required></label><label>RW<input v-model="selected.rw" maxlength="3" required></label><label>Status akun<select v-model="selected.is_active"><option :value="true">Aktif</option><option :value="false">Nonaktif</option></select></label><label class="wide">Alamat lengkap<textarea v-model="selected.full_address" required></textarea></label></div><p v-if="error" class="login-error">{{error}}</p><footer class="detail-actions"><button type="button" class="secondary-button" @click="cancelEdit">Batal</button><button type="submit" class="edit-button" :disabled="saving">{{saving?'Menyimpan…':'Simpan perubahan'}}</button></footer></form><template v-else><div class="detail-summary"><article><b>{{patientsOf(selected).length}}</b><span>Pasien binaan</span></article><article><b>RT {{selected.rt??'—'}}</b><span>Wilayah RT</span></article><article><b>RW {{selected.rw??'—'}}</b><span>Wilayah RW</span></article></div><section class="detail-section"><h3>Informasi kontak</h3><dl class="detail-grid"><div><dt>NIK</dt><dd>{{selected.nik}}</dd></div><div><dt>Nomor WhatsApp</dt><dd>{{selected.phone}}</dd></div><div><dt>Jenis kelamin</dt><dd>{{selected.gender==='L'?'Laki-laki':selected.gender==='P'?'Perempuan':'Belum tersedia'}}</dd></div><div><dt>Tanggal lahir</dt><dd>{{displayDate(selected.birth_date)}}</dd></div><div class="wide"><dt>Alamat</dt><dd>{{selected.full_address||'Belum tersedia'}} · RT {{selected.rt??'—'}} / RW {{selected.rw??'—'}}</dd></div></dl></section><section class="detail-section"><div class="section-title"><div><h3>Pasien binaan</h3><p>Pasien yang sedang didampingi oleh kader ini.</p></div><span>{{patientsOf(selected).length}} pasien</span></div><div v-if="patientsOf(selected).length" class="patient-chips"><span v-for="(patient,index) in patientsOf(selected)" :key="patient.id"><b>{{index+1}}</b>{{patient.full_name}}</span></div><p v-else class="empty-patients">Belum ada pasien yang ditugaskan.</p></section><footer class="detail-actions"><button type="button" class="secondary-button" @click="selected=null">Tutup</button><button type="button" class="edit-button" @click="editing=true">Edit data</button><button type="button" class="danger-button" :disabled="deleting" @click="remove">{{deleting?'Menghapus…':'Hapus kader'}}</button></footer></template></section></div></main></template>

<style scoped>
