3,1fr);gap:12px;margin:-14px 24px 0;position:relative}.detail-summary article{padding:14px;border:1px solid #dcefeb;border-radius:14px;background:#fff;box-shadow:0 8px 18px #17665d12}.detail-summary b{display:block;font-size:17px;color:#087e72}.detail-summary span{font-size:10px;color:#708b92}.detail-section,.edit-form{padding:20px 24px 0}.detail-section h3,.edit-form h3{margin:0;color:#173f59;font-size:15px}.detail-grid,.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:13px 0 0}.detail-grid div{padding:12px;border-radius:11px;background:#f6fbfa}.detail-grid .wide,.form-grid .wide{grid-column:1/-1}.detail-grid dt{font-size:10px;color:#6e8991;text-transform:uppercase;font-weight:700}.detail-grid dd{margin:5px 0 0;font-size:13px;color:#294e60;overflow-wrap:anywhere}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:start}.section-title p,.edit-form>p{margin:4px 0 0;font-size:11px;color:#748d94}.section-title>span{border-radius:999px;padding:6px 9px;background:#e6f7f3;color:#087e72;font-size:10px;font-weight:700}.patient-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:13px}.patient-chips span{display:flex;align-items:center;gap:7px;padding:8px 10px;border:1px solid #dbeee9;border-radius:999px;background:#fbfefd;color:#245265;font-size:12px}.patient-chips b{display:grid;place-items:center;width:19px;height:19px;border-radius:50%;background:#0b9385;color:#fff;font-size:10px}.empty-patients{margin:12px 0 0;padding:12px;border-radius:10px;background:#fff9e9;color:#9a741d;font-size:12px}.form-grid label{font-size:12px;font-weight:700;color:#214a60}.form-grid input,.form-grid select,.form-grid textarea{box-sizing:border-box;display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #cfe4df;border-radius:9px;background:#fbfefd;font:13px Arial;color:#214a60}.form-grid textarea{min-height:80px;resize:vertical}.form-grid small{display:block;margin-top:4px;font-size:10px;font-weight:400;color:#738e95}.detail-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:22px;padding:18px 24px;border-top:1px solid #e4efed}.secondary-button{background:#edf7f5;color:#087e72}.danger-button{background:#fff0ee;color:#b43d34}.danger-button:disabled,.edit-button:disabled{opacity:.6;cursor:wait}@media(max-width:650px){.cadre-modal{padding:10px}.detail-hero{padding:24px 18px;align-items:flex-start}.detail-hero img{width:62px;height:62px}.detail-hero h2{font-size:19px}.wa-hero{margin:40px 0 0 -70px}.detail-summary{margin:-10px 14px 0;gap:7px}.detail-summary article{padding:10px}.detail-section,.edit-form{padding:18px 14px 0}.detail-grid,.form-grid{grid-template-columns:1fr}.detail-grid .wide,.form-grid .wide{grid-column:auto}.detail-actions{padding:16px 14px;flex-wrap:wrap}}
</style>
